  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--card-border);
  padding: 0 24px;
}
.nav-inner {
  max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  height: 72px;
}
.nav-logo {
  font-size: 1.4rem; font-weight: 700; color: var(--text-white);
  letter-spacing: -0.02em;
}
.nav-logo span { color: var(--accent-green); }

.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { color: var(--text-secondary); font-size: 0.9rem; font-weight: 500; transition: color var(--transition); }
.nav-links a:hover { color: var(--text-white); }

.nav-dropdown { position: relative; }
.nav-dropdown > a { cursor: pointer; display: flex; align-items: center; gap: 4px; }
.nav-dropdown > a::after {
  content: ''; display: inline-block; width: 0; height: 0;
  border-left: 4px solid transparent; border-right: 4px solid transparent;
  border-top: 4px solid currentColor; margin-top: 2px;
}
.dropdown-menu {
  position: absolute; top: calc(100% + 12px); left: -12px;
  background: var(--navy-mid); border: 1px solid var(--card-border);
  border-radius: 8px; padding: 8px 0; min-width: 200px;
  opacity: 0; visibility: hidden; transform: translateY(-8px);
  transition: all var(--transition); box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: block; padding: 10px 20px; color: var(--text-secondary);
  font-size: 0.85rem; transition: all var(--transition);
}
.dropdown-menu a:hover { color: var(--text-white); background: rgba(0,180,216,0.08); }

.btn-demo {
  background: var(--accent-green); color: var(--navy) !important;
  padding: 10px 24px; border-radius: 6px; font-weight: 600;
  font-size: 0.9rem; transition: all var(--transition); border: none; cursor: pointer;
  display: inline-block; text-align: center;
}
.btn-demo:hover { background: #5aad3a; color: var(--navy) !important; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(108,194,74,0.3); }

.btn-outline {
  border: 1px solid var(--accent-teal); color: var(--accent-teal) !important;
  padding: 10px 24px; border-radius: 6px; font-weight: 600;
  font-size: 0.9rem; transition: all var(--transition); background: transparent;
  cursor: pointer; display: inline-block; text-align: center;
}
.btn-outline:hover { background: rgba(0,180,216,0.1); transform: translateY(-1px); }

.mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 4px; }
.mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--text-primary); margin: 5px 0; transition: var(--transition); }

/* ===== HERO ===== */
.hero {
  padding: 160px 0 100px;
  background: linear-gradient(170deg, var(--navy) 0%, var(--navy-mid) 50%, var(--brand-navy) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -50%; right: -20%;
  width: 600px; height: 600px; border-radius: 50%;
  background: radial-gradient(circle, rgba(0,180,216,0.06) 0%, transparent 70%);
}
.hero .container { position: relative; z-index: 1; }
.hero-label {
  display: inline-block; font-size: 0.75rem; font-weight: 600;
  letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--accent-teal); margin-bottom: 16px;
  padding: 6px 14px; border: 1px solid rgba(0,180,216,0.25);
  border-radius: 20px;
}
.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.5rem); font-weight: 800;
  color: var(--text-white); line-height: 1.1; margin-bottom: 20px;
  max-width: 700px; letter-spacing: -0.02em;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary);
  max-width: 560px; margin-bottom: 32px; line-height: 1.7;
}
.hero-btns { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== SECTION PATTERNS ===== */
section { padding: 100px 0; }
.section-label {
  font-size: 0.75rem; font-weight: 600; letter-spacing: 0.15em;
  text-transform: uppercase; color: var(--accent-teal); margin-bottom: 12px;
}
.section-title {
  font-size: clamp(1.8rem, 3.5vw, 2.5rem); font-weight: 700;
  color: var(--text-white); margin-bottom: 16px; letter-spacing: -0.02em;
}
.section-desc {
  font-size: 1.05rem; color: var(--text-secondary); max-width: 640px;
  line-height: 1.7; margin-bottom: 48px;
}

.bg-dark { background: var(--navy); }
.bg-mid { background: var(--navy-mid); }
.bg-gradient { background: linear-gradient(180deg, var(--navy-mid) 0%, var(--navy) 100%); }

/* ===== CARDS ===== */
.card {
  background: var(--card-bg); border: 1px solid var(--card-border);
  border-radius: 12px; padding: 32px; transition: all var(--transition);
}
.card:hover { border-color: rgba(0,180,216,0.3); transform: translateY(-4px); box-shadow: 0 8px 32px rgba(0,0,0,0.3); }
.card h3 { font-size: 1.15rem; font-weight: 600; color: var(--text-white); margin-bottom: 10px; }
.card p { font-size: 0.9rem; color: var(--text-secondary); line-height: 1.6; }

.card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.card-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }

.card-icon {
  width: 48px; height: 48px; border-radius: 10px;
  background: rgba(0,180,216,0.1); display: flex; align-items: center;
  justify-content: center; margin-bottom: 20px;
}
.card-icon svg { width: 24px; height: 24px; stroke: var(--accent-teal); fill: none; stroke-width: 1.5; }

/* ===== TABS ===== */
.tabs-nav {
  display: flex; gap: 0; border-bottom: 2px solid rgba(255,255,255,0.08);
  margin-bottom: 40px; overflow-x: auto;
}
.tab-btn {
  padding: 14px 28px; background: none; border: none; cursor: pointer;
  font-family: var(--font-family); font-size: 0.9rem; font-weight: 500;
  color: var(--text-secondary); position: relative; white-space: nowrap;
  transition: color var(--transition);
}
.tab-btn::after {
  content: ''; position: absolute; bottom: -2px; left: 0; right: 0;
  height: 2px; background: var(--accent-teal); transform: scaleX(0);
  transition: transform var(--transition);
}
.tab-btn.active { color: var(--text-white); }
.tab-btn.active::after { transform: scaleX(1); }
.tab-btn:hover { color: var(--text-white); }

.tab-panel { display: none; animation: fadeIn 0.4s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== ACCORDION ===== */
.accordion-item {
  border: 1px solid var(--card-border); border-radius: 10px;
  margin-bottom: 12px; overflow: hidden; background: var(--card-bg);
  transition: border-color var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.25); }
.accordion-header {
  padding: 20px 28px; cursor: pointer; display: flex;
  justify-content: space-between; align-items: center;
  font-weight: 600; color: var(--text-white); font-size: 1rem;
  background: none; border: none; width: 100%; font-family: var(--font-family);
  text-align: left;
}
.accordion-header .icon {
  width: 24px; height: 24px; position: relative; flex-shrink: 0; margin-left: 16px;
}
.accordion-header .icon::before,
.accordion-header .icon::after {
  content: ''; position: absolute; background: var(--accent-teal);
  top: 50%; left: 50%; transform: translate(-50%, -50%);
  transition: transform var(--transition);
}
.accordion-header .icon::before { width: 14px; height: 2px; }
.accordion-header .icon::after { width: 2px; height: 14px; }
.accordion-item.open .accordion-header .icon::after { transform: translate(-50%, -50%) rotate(90deg); opacity: 0; }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.4s ease;
}
.accordion-item.open .accordion-body { max-height: 300px; }
.accordion-body-inner { padding: 0 28px 24px; color: var(--text-secondary); font-size: 0.95rem; line-height: 1.7; }

/* ===== STATS CIRCLES ===== */
.stats-row { display: flex; justify-content: center; gap: 64px; flex-wrap: wrap; margin: 48px 0; }
.stat-item { text-align: center; }
.stat-circle {
  width: 140px; height: 140px; border-radius: 50%; position: relative;
  display: flex; align-items: center; justify-content: center; margin: 0 auto 16px;
}
.stat-circle svg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.stat-circle circle {
  fill: none; stroke-width: 4; cx: 70; cy: 70; r: 64;
}
.stat-circle .bg { stroke: rgba(255,255,255,0.06); }
.stat-circle .fill { stroke: var(--accent-teal); stroke-dasharray: 402; stroke-linecap: round; transition: stroke-dashoffset 1.5s ease; }
.stat-value { font-size: 2rem; font-weight: 800; color: var(--text-white); position: relative; z-index: 1; }
.stat-label { font-size: 0.85rem; color: var(--text-secondary); max-width: 160px; margin: 0 auto; }

/* ===== TIMELINE ===== */
.timeline { max-width: 700px; margin: 0 auto; }
.timeline-item { display: flex; align-items: center; gap: 24px; margin-bottom: 32px; }
.timeline-duration {
  min-width: 120px; font-size: 1.5rem; font-weight: 800;
  color: var(--accent-green); text-align: right;
}
.timeline-content { flex: 1; }
.timeline-content p { font-size: 0.95rem; color: var(--text-secondary); margin-bottom: 8px; }
.progress-bar { height: 6px; background: rgba(255,255,255,0.06); border-radius: 3px; overflow: hidden; }
.progress-bar .fill { height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--accent-teal), var(--accent-green)); transition: width 1.5s ease; }

/* ===== TESTIMONIAL CAROUSEL ===== */
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.5s ease; }
.carousel-slide { min-width: 100%; padding: 0 24px; }
.testimonial-card {
  background: var(--card-bg); border: 1px solid var(--card-border);
  border-radius: 12px; padding: 40px; max-width: 700px; margin: 0 auto;
}
.testimonial-card blockquote {
  font-size: 1.1rem; color: var(--text-primary); line-height: 1.8;
  font-style: italic; margin-bottom: 20px;
}
.testimonial-card cite { font-size: 0.85rem; color: var(--accent-teal); font-style: normal; }
.carousel-dots { display: flex; justify-content: center; gap: 10px; margin-top: 28px; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%; border: none; cursor: pointer;
  background: rgba(255,255,255,0.15); transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-teal); transform: scale(1.2); }

/* ===== DIAGRAM ===== */
.diagram-container {
  background: var(--card-bg); border: 1px solid var(--card-border);
  border-radius: 16px; padding: 48px; margin-top: 40px;
}
.diagram-pillars { display: flex; gap: 32px; justify-content: center; align-items: stretch; flex-wrap: wrap; }
.diagram-pillar {
  flex: 1; min-width: 220px; max-width: 320px; text-align: center; position: relative;
  padding: 32px 24px; border-radius: 12px;
  background: linear-gradient(180deg, rgba(0,180,216,0.08) 0%, transparent 100%);
  border: 1px solid rgba(0,180,216,0.15);
}
.diagram-pillar h4 { color: var(--text-white); font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.diagram-pillar p { font-size: 0.85rem; color: var(--text-secondary); }
.diagram-pillar .pillar-icon {
  width: 56px; height: 56px; border-radius: 50%;
  background: rgba(0,180,216,0.12); display: flex; align-items: center; justify-content: center;
  margin: 0 auto 16px;
}
.diagram-pillar .pillar-icon svg { width: 28px; height: 28px; stroke: var(--accent-teal); fill: none; stroke-width: 1.5; }
.diagram-connector {
  display: flex; align-items: center; justify-content: center;
  color: var(--accent-teal); font-size: 1.5rem; padding: 0 8px;
}
.diagram-center-label {
  text-align: center; margin-bottom: 32px;
}
.diagram-center-label h3 { color: var(--text-white); font-size: 1.3rem; margin-bottom: 8px; }
.diagram-center-label p { color: var(--text-secondary); font-size: 0.9rem; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  background: linear-gradient(135deg, var(--brand-navy) 0%, var(--navy-mid) 100%);
  border: 1px solid var(--card-border); border-radius: 12px;
  padding: 40px 48px; display: flex; align-items: center;
  justify-content: space-between; flex-wrap: wrap; gap: 24px;
}
.featured-banner h3 { font-size: 1.4rem; color: var(--text-white); }
.featured-banner p { color: var(--text-secondary); font-size: 1rem; margin-top: 4px; }

/* ===== CTA BANNER ===== */
.cta-banner {
  background: linear-gradient(135deg, rgba(0,119,182,0.15) 0%, rgba(108,194,74,0.08) 100%);
  border: 1px solid rgba(0,180,216,0.2); border-radius: 16px;
  padding: 60px 48px; text-align: center;
}
.cta-banner h2 { font-size: 2rem; color: var(--text-white); margin-bottom: 16px; }
.cta-banner p { color: var(--text-secondary); font-size: 1.05rem; max-width: 560px; margin: 0 auto 32px; line-height: 1.7; }

/* ===== FORM ===== */
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.form-group { display: flex; flex-direction: column; }
.form-group.full-width { grid-column: 1 / -1; }
.form-group label {
  font-size: 0.85rem; font-weight: 500; color: var(--text-secondary);
  margin-bottom: 6px;
}
.form-group label .required { color: #ef4444; }
.form-group input,
.form-group select,
.form-group textarea {
  background: var(--navy); border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px; padding: 12px 16px; font-size: 0.95rem;
  color: var(--text-primary); font-family: var(--font-family);
  transition: border-color var(--transition);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none; border-color: var(--accent-teal);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}
.form-group input.error,
.form-group select.error { border-color: #ef4444; }
.form-group .error-msg { font-size: 0.75rem; color: #ef4444; margin-top: 4px; display: none; }
.form-group input.error + .error-msg,
.form-group select.error + .error-msg { display: block; }
.form-group textarea { resize: vertical; min-height: 100px; }
.form-success {
  display: none; text-align: center; padding: 40px;
  color: var(--accent-green); font-size: 1.1rem;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy-mid); border-top: 1px solid var(--card-border);
  padding: 64px 0 32px;
}
.footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; margin-bottom: 48px; }
.footer-brand p { color: var(--text-secondary); font-size: 0.85rem; margin-top: 12px; line-height: 1.7; max-width: 300px; }
.footer-col h4 { font-size: 0.8rem; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-white); margin-bottom: 16px; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { color: var(--text-secondary); font-size: 0.85rem; }
.footer-col a:hover { color: var(--accent-teal); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px;
}
.footer-bottom p { font-size: 0.8rem; color: var(--text-secondary); }
.footer-logins { display: flex; gap: 16px; }
.footer-logins a { font-size: 0.8rem; color: var(--text-secondary); padding: 6px 12px; border: 1px solid rgba(255,255,255,0.08); border-radius: 4px; }
.footer-logins a:hover { border-color: var(--accent-teal); color: var(--accent-teal); }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999;
  background: var(--navy-mid); border-top: 1px solid var(--card-border);
  padding: 20px 24px; display: flex; align-items: center;
  justify-content: center; gap: 24px; flex-wrap: wrap;
  box-shadow: 0 -8px 32px rgba(0,0,0,0.4);
}
.cookie-banner.hidden { display: none; }
.cookie-banner p { font-size: 0.85rem; color: var(--text-secondary); max-width: 600px; }
.cookie-banner .btn-sm {
  padding: 8px 20px; border-radius: 6px; font-size: 0.85rem;
  font-weight: 600; cursor: pointer; border: none; font-family: var(--font-family);
  transition: all var(--transition);
}
.cookie-accept { background: var(--accent-green); color: var(--navy); }
.cookie-accept:hover { background: #5aad3a; }
.cookie-decline { background: transparent; color: var(--text-secondary); border: 1px solid rgba(255,255,255,0.1) !important; }
.cookie-decline:hover { border-color: rgba(255,255,255,0.3) !important; color: var(--text-white); }

/* ===== SECURITY FEATURE LIST ===== */
.security-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 24px; }
.security-card { padding: 32px; }
.security-card .card-icon { background: rgba(108,194,74,0.1); }
.security-card .card-icon svg { stroke: var(--accent-green); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .diagram-pillars { flex-direction: column; align-items: center; }
  .diagram-connector { transform: rotate(90deg); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-links.open {
    display: flex; flex-direction: column; position: absolute;
    top: 72px; left: 0; right: 0; background: var(--navy-mid);
    padding: 24px; gap: 16px; border-bottom: 1px solid var(--card-border);
  }
  .mobile-toggle { display: block; }

  .hero { padding: 120px 0 60px; }
  .hero h1 { font-size: 2rem; }
  section { padding: 60px 0; }

  .card-grid, .card-grid-2 { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .stats-row { gap: 32px; }
  .timeline-item { flex-direction: column; text-align: center; }
  .timeline-duration { text-align: center; }
  .featured-banner { flex-direction: column; text-align: center; padding: 28px; }
  .footer-grid { grid-template-columns: 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .tabs-nav { gap: 0; }
  .tab-btn { padding: 12px 16px; font-size: 0.8rem; }
  .cta-banner { padding: 40px 24px; }
  .diagram-container { padding: 24px; }
}

@media (max-width: 480px) {
  .hero-btns { flex-direction: column; }
  .btn-demo, .btn-outline { width: 100%; text-align: center; }
  .cookie-banner { flex-direction: column; text-align: center; }
}
